def pages():
    out = []
    for e in EVENTS:
        groups = [("Instagram captions", [(l, "Instagram", t) for l, t in e["ig"]]),
                  ("TikTok captions", [(l, "TikTok", t) for l, t in e["tt"]]),
                  ("WhatsApp status captions", [(l, "WhatsApp status", t) for l, t in e["wa"]])]
        out.append(dict(path=f"/captions/{e['slug']}/", section="captions", crumb=e["name"] + " captions",
                        title=e["title"] + " | ListingKit" if len(e["title"]) < 60 else e["title"],
                        meta=e["meta"], h1=f"{e['name']} captions for real estate", eyebrow="Real estate captions",
                        lede=e["lede"], intro=e["intro"], groups=groups, tips=e["tips"],
                        tips_title=f"How to write {e['name'].lower()} posts that get enquiries", faq=e["faq"],
                        related=e["related"] + [f"/captions/{x['slug']}/" for x in EVENTS if x["slug"] != e["slug"]][:4],
                        blurb=e["lede"][:120]))
    return out
